name: CI

on:
  push:
    branches: [main]
  pull_request:
  workflow_dispatch:

permissions:
  contents: read

concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: true

jobs:
  quality:
    name: Go, React, E2E, and offline checks
    runs-on: ubuntu-24.04
    timeout-minutes: 25
    steps:
      - name: Check out source
        uses: actions/checkout@v4

      - name: Set up Go
        uses: actions/setup-go@v5
        with:
          go-version-file: go.mod
          cache: true

      - name: Set up Node.js
        uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm
          cache-dependency-path: web/package-lock.json

      - name: Install frontend dependencies
        working-directory: web
        run: npm ci --no-audit --no-fund

      - name: Check formatting and lint
        run: |
          unformatted="$(find . -path './web' -prune -o -path './.git' -prune -o -type f -name '*.go' -print0 | xargs -0 gofmt -l)"
          test -z "$unformatted"
          npm --prefix web run lint

      - name: Run Go tests
        run: go test -race . ./cmd/... ./internal/... ./migrations/... ./openapi/...

      - name: Run React tests
        run: npm --prefix web test

      - name: Build and check offline frontend
        run: |
          npm --prefix web run build
          ./scripts/check-offline-assets.sh web/dist
          ./scripts/embed-web.sh

      - name: Build Go service
        run: go build -trimpath -buildvcs=false -o /tmp/appstore-ci ./cmd/server

      - name: Validate environment and documentation contracts
        run: |
          ./scripts/check-env-contract.sh
          ./scripts/check-docs.sh

      - name: Install Playwright browser
        working-directory: web
        run: npx playwright install --with-deps chromium

      - name: Run desktop and mobile E2E tests
        working-directory: web
        run: npm run test:e2e

      - name: Upload Playwright report on failure
        if: failure()
        uses: actions/upload-artifact@v4
        with:
          name: playwright-report
          path: web/playwright-report/
          if-no-files-found: ignore
          retention-days: 7

  image:
    name: Non-root offline image smoke test
    needs: quality
    runs-on: ubuntu-24.04
    timeout-minutes: 20
    steps:
      - name: Check out source
        uses: actions/checkout@v4

      - name: Set up Docker Buildx
        uses: docker/setup-buildx-action@v3

      - name: Build CI image
        run: |
          docker build --platform linux/amd64 --load \
            --build-arg VERSION=v0.0.0 \
            --build-arg COMMIT="${GITHUB_SHA}" \
            --build-arg BUILD_DATE="$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
            --tag appstore:v0.0.0 .

      - name: Verify non-root image and embedded UI
        run: |
          test "$(docker image inspect --format '{{ .Config.User }}' appstore:v0.0.0)" = "appstore:appstore"
          ./scripts/smoke-image.sh appstore:v0.0.0
# AppStore

AppStore는 누구나 사내 애플리케이션을 탐색하고, 인증된 사용자가 앱을 등록·관리하며, 조직 정책에 따라 검토·승인할 수 있는 오프라인 운영형 Developer App Store입니다.

> 보는 것은 자유롭게, 등록하는 순간부터 인증하고, 관리 권한은 명확하게 분리합니다.

![AppStore v2.11.3 공개 카탈로그 전체 화면](docs/assets/screenshots/captures/today-desktop.webp)

화면 이미지는 비밀이 없는 결정적 fixture로 생성한 v2.11.3 실제 UI의 전체 페이지 WebP 캡처입니다. Desktop·mobile 전체 route의 파일과 SHA-256은 [screenshot manifest](docs/assets/screenshots/manifest.json)에서 검증합니다.

## 핵심 기능

- 로그인 없는 Today, 앱 카탈로그, 카테고리, 검색, 상세와 즐겨찾기
- Keycloak Authorization Code + PKCE 기반 OIDC SSO와, 저장 전 Issuer도 시험하고 실패 원인을 그대로 알려 주는 discovery 연결 시험
- 개인 영역과 서비스 관리자 영역의 명확한 분리
- 관리자 앱 카탈로그의 검색·상태 필터와 앱 상세 정보 수정·게시 상태 변경·영구 삭제
- 기본 OFF인 선택형 팀장 검토·승인·반려 Workflow와, 승인 ON일 때 SSO 사용자 기본 역할을 contributor로 올리는 정책
- 기본 OFF인 SecCheck 보안 심의 연동 — 등록자가 최종 승인을 받아야 앱이 검토 대기로 넘어가고, 승인된 앱에는 **보안 심의 완료** 라벨이 붙습니다
- 원문을 저장하지 않는 개인 API·MCP Key와 회전 Grace Period
- 변경 가능한 역할, permission과 Key permission template
- REST API v1, OpenAPI 문서와 권한별 MCP tool
- SSE 기본 AI streaming, cancel 전파와 최대 262,144 token 설정
- Ctrl/Cmd+K 빠른 이동 팔레트로 메뉴·앱·관리 화면 한 번에 검색
- PostgreSQL에 저장해 업그레이드에도 유지되는 로고·파비콘 업로드와 주소 가져오기
- 앱마다 최대 10개까지 첨부하는 가이드 문서(PDF·Office·Markdown, 파일당 20MB)와 앱 상세 화면의 로그인 없는 내려받기
- 바이너리에 실린 사내 서비스별 사용자·관리자 가이드 — 기동할 때마다 소문자로 바꾼 slug가 같은 앱에 자동 첨부되고, 바뀐 파일만 교체
- URL 기반 메뉴·검색 상태, SPA refresh fallback과 전역 오류 상태
- 로그인 화면과 profile context menu의 build version 표시
- 기본 OFF인 방문 추적 스크립트 삽입 — Momento(사내 수집기, 같은 오리진 프록시)·GA4·GTM·Matomo·직접 붙여 넣기, 요청마다 nonce를 붙인 CSP와 차단된 출처 표시
- 감사 로그, 암호화된 OIDC·AI secret과 non-root container 운영

## 기술 구조

```text
Browser
  └─ React 19 + TypeScript + Vite + Tailwind CSS
       └─ Go HTTP service :8080
            ├─ React SPA (go:embed)
            ├─ REST / OpenAPI
            ├─ Keycloak OIDC session
            ├─ AI SSE proxy
            ├─ MCP endpoint
            └─ PostgreSQL migrations + seed (go:embed)
```

Frontend는 shadcn/ui의 소스 소유 방식과 접근성 원칙을 따르는 로컬 컴포넌트, Tailwind CSS, Lucide, TanStack Query 조합을 사용합니다. 런타임 CDN, Google Fonts와 원격 홍보 이미지를 사용하지 않습니다.

## 접근 정책

| 영역 | 정책 |
| --- | --- |
| `/`, `/today`, `/apps`, `/apps/:slug`, 카테고리·검색 | Anonymous |
| `/favorites` | Anonymous + Local Storage |
| `/submit`, `/my/*` | SSO |
| `/review` | SSO + Reviewer |
| `/admin/*` | SSO + Admin |

## 런타임 환경변수

애플리케이션 코드가 읽는 환경변수는 정확히 네 개입니다.

| 이름 | 필수 | 설명 |
| --- | --- | --- |
| `POSTGRES_DSN` | 예 | PostgreSQL 연결 문자열 |
| `BOOTSTRAP_ADMIN` | 예 | 최초·복구 Super Admin 식별자 |
| `BOOTSTRAP_ADMIN_PASSWORD` | 예 | 최소 12자의 Bootstrap 비밀번호 |
| `ENCRYPTION_KEY` | 예 | 32-byte secret 암호화 key. 64자리 hex 또는 32 byte의 base64 표현 권장 |

서비스 URL, OIDC Issuer·Client ID·Client Secret, role/group mapping, Workflow, AI, API, MCP와 Key 정책은 환경변수가 아니라 Admin UI와 PostgreSQL에서 관리합니다. Secret은 `ENCRYPTION_KEY`로 인증 암호화되고 조회 API에서는 원문을 반환하지 않습니다.

import {
  QueryClient,
  QueryClientProvider,
  useQuery,
  useQueryClient,
} from "@tanstack/react-query";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type PropsWithChildren,
} from "react";
import {
  beginSilentSso,
  clearSilentSsoState,
  markSignedOut,
  shouldAttemptSilentSso,
} from "../features/auth/silent-sso";
import { useLocation } from "react-router-dom";
import { api, setCsrfToken } from "../lib/api";
import type { Session } from "../types";

export type ThemePreference = "light" | "dark" | "system";

interface ThemeContextValue {
  preference: ThemePreference;
  resolved: "light" | "dark";
  setPreference: (preference: ThemePreference) => void;
  toggle: () => void;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);
const AuthContext = createContext<{
  session?: Session;
  isPending: boolean;
  error: Error | null;
  refresh: () => Promise<void>;
  logout: () => Promise<void>;
} | null>(null);

function initialTheme(): ThemePreference {
  const stored = localStorage.getItem("appstore.theme");
  return stored === "light" || stored === "dark" || stored === "system"
    ? stored
    : "system";
}

function ThemeProvider({ children }: PropsWithChildren) {
  const [preference, setPreferenceState] =
    useState<ThemePreference>(initialTheme);
  const publicConfig = useQuery({
    queryKey: ["public-config"],
    queryFn: ({ signal }) => api.publicConfig(signal),
    staleTime: 60_000,
  });
  const [systemDark, setSystemDark] = useState(
    () => matchMedia("(prefers-color-scheme: dark)").matches,
  );
  const resolved =
    preference === "system" ? (systemDark ? "dark" : "light") : preference;

  useEffect(() => {
    if (localStorage.getItem("appstore.theme")) return;
    const configured = publicConfig.data?.theme;
    if (
      configured === "light" ||
      configured === "dark" ||
      configured === "system"
    ) {
      setPreferenceState(configured);
    }
  }, [publicConfig.data?.theme]);

  useEffect(() => {
    const query = matchMedia("(prefers-color-scheme: dark)");
    const listener = (event: MediaQueryListEvent) =>
      setSystemDark(event.matches);
    query.addEventListener("change", listener);
    return () => query.removeEventListener("change", listener);
  }, []);

  useEffect(() => {
    document.documentElement.dataset.theme = resolved;
    document.documentElement.style.colorScheme = resolved;
  }, [resolved]);

  const setPreference = useCallback((next: ThemePreference) => {
    localStorage.setItem("appstore.theme", next);
    setPreferenceState(next);
  }, []);

  const value = useMemo<ThemeContextValue>(
    () => ({
      preference,
      resolved,
      setPreference,
      toggle: () => setPreference(resolved === "dark" ? "light" : "dark"),
    }),
    [preference, resolved, setPreference],
  );

  return (
    <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
  );
}

export function AuthProvider({ children }: PropsWithChildren) {
  const queryClient = useQueryClient();
  const query = useQuery({
    queryKey: ["session"],
    queryFn: ({ signal }) => api.session(signal),
    retry: false,
    staleTime: 30_000,
  });

  useEffect(() => setCsrfToken(query.data?.csrfToken), [query.data?.csrfToken]);

  const value = useMemo(
    () => ({
      session: query.data,
      isPending: query.isPending,
      error: query.error,
      refresh: async () => {
        await queryClient.invalidateQueries({ queryKey: ["session"] });
      },
      logout: async () => {
        // Marked before the session goes away: a silent SSO attempt right
        // after signing out would make the sign-out look broken.
        markSignedOut();
        await api.logout();
        setCsrfToken();
        queryClient.setQueryData(["session"], {
          authenticated: false,
        } satisfies Session);
        await queryClient.invalidateQueries();
      },
    }),
    [query.data, query.error, query.isPending, queryClient],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: 1, refetchOnWindowFocus: false, staleTime: 15_000 },
    mutations: { retry: 0 },
  },
});

/**
 * Applies the configured favicon to the live document. The bundled icon link is
 * static, so an administrator's upload would otherwise never show in the tab.
 */
function FaviconEffect() {
  const config = useQuery({
    queryKey: ["public-config"],
    queryFn: ({ signal }) => api.publicConfig(signal),
    staleTime: 60_000,
  });
  const faviconUrl = config.data?.faviconUrl;
  useEffect(() => {
    if (!faviconUrl) return;
    const link =
      document.querySelector<HTMLLinkElement>('link[rel="icon"]') ??
      document.head.appendChild(
        Object.assign(document.createElement("link"), { rel: "icon" }),
      );
    const previous = link.getAttribute("href");
    link.setAttribute("href", faviconUrl);
    return () => {
      if (previous === null) link.remove();
      else link.setAttribute("href", previous);
    };
  }, [faviconUrl]);
  return null;
}

/**
 * Tries a silent SSO sign-in once the session and public config are known.
 * Someone already signed in at the identity provider then lands on the page
 * they opened without seeing a login screen; someone who is not is sent back
 * to /login?sso=none by the callback and never bounced again.
 */
function SilentSsoEffect() {
  const auth = useAuth();
  const location = useLocation();
  const config = useQuery({
    queryKey: ["public-config"],
    queryFn: ({ signal }) => api.publicConfig(signal),
    staleTime: 60_000,
  });
  const authenticated = auth.session?.authenticated ?? false;
  const settled = !auth.isPending && !auth.error && !!config.data;
  useEffect(() => {
    if (!settled) return;
    if (authenticated) {
      // A session exists again, so a later sign-out may be followed by a
      // silent attempt in a new tab as usual.
      clearSilentSsoState();
      return;
    }
    if (
      !shouldAttemptSilentSso({
        config: config.data,
        pathname: location.pathname,
        search: location.search,
      })
    )
      return;
    beginSilentSso(location.pathname + location.search);
  }, [settled, authenticated, config.data, location.pathname, location.search]);
  return null;
}

export function AppProviders({ children }: PropsWithChildren) {
  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider>
        <AuthProvider>
          <FaviconEffect />
          <SilentSsoEffect />
          {children}
        </AuthProvider>
      </ThemeProvider>
    </QueryClientProvider>
  );
}

export function useTheme(): ThemeContextValue {
  const value = useContext(ThemeContext);
  if (!value) throw new Error("ThemeProvider가 필요합니다.");
  return value;
}

export function useAuth() {
  const value = useContext(AuthContext);
  if (!value) throw new Error("AuthProvider가 필요합니다.");
  return value;
}
