func (r *Repository) UpdateApp(ctx context.Context, id uuid.UUID, input model.AppInput) (model.App, error) {
	input, err := validateAppInput(input)
	if err != nil {
		return model.App{}, err
	}
	categoryID, err := uuid.Parse(input.CategoryID)
	if err != nil {
		return model.App{}, fmt.Errorf("update app category: %w", ErrInvalid)
	}
	tx, err := r.pool.Begin(ctx)
	if err != nil {
		return model.App{}, normalizeError("begin app update", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	before, err := scanApp(tx.QueryRow(ctx, `SELECT `+appColumns+appFrom+` WHERE a.id = $1 FOR UPDATE OF a`, id))
	if err != nil {
		return model.App{}, normalizeError("lock updated app", err)
	}
	result, err := tx.Exec(ctx, `
		UPDATE apps SET category_id = $2, name = $3, slug = $4, summary = $5,
			description = $6, icon = $7, gradient = $8, service_url = $9,
			tags = $10, screenshots = $11, language = $12, framework = $13,
			supports_mcp = $14, supports_api = $15, team = $16,
			app_version = $17, visibility = $18, updated_at = now()
		WHERE id = $1`, id, categoryID, input.Name, input.Slug, input.Summary,
		input.Description, input.Icon, input.Gradient, input.ServiceURL,
		jsonValue(input.Tags), jsonValue(input.Screenshots), input.Language,
		input.Framework, input.SupportsMCP, input.SupportsAPI, input.Team,
		input.Version, input.Visibility)
	if err != nil {
		return model.App{}, normalizeError("update app", err)
	}
	if result.RowsAffected() == 0 {
		return model.App{}, fmt.Errorf("update app: %w", ErrNotFound)
	}
	// Changed content means the approval SecCheck gave no longer describes this
	// app, so the challenge rotates and the owner goes round again.
	if securityRelevantChange(before, input) {
		if err := rotateAppChallenge(ctx, tx, id); err != nil {
			return model.App{}, err
		}
	}
	if err := tx.Commit(ctx); err != nil {
		return model.App{}, normalizeError("commit app update", err)
	}
	return r.GetAppByID(ctx, id)
}
func rotateAppChallenge(ctx context.Context, tx pgx.Tx, appID uuid.UUID) error {
	if _, err := tx.Exec(ctx, `
		UPDATE apps SET security_challenge_nonce = gen_random_uuid(), security_review_id = NULL
		WHERE id = $1`, appID); err != nil {
		return normalizeError("rotate app security challenge", err)
	}
	return nil
}

// requireSecurityCheck is the gate every transition into the review queue or
// the catalog passes through while the feature is on.
func requireSecurityCheck(ctx context.Context, tx pgx.Tx, appID uuid.UUID) error {
	var verified bool
	err := tx.QueryRow(ctx, `
		SELECT `+securityVerifiedSQL+`
		FROM apps a
		CROSS JOIN security_check_settings ss
		LEFT JOIN app_security_checks sc ON sc.review_id = a.security_review_id
		WHERE a.id = $1`, appID).Scan(&verified)
	if err != nil {
		return normalizeError("check app security verification", err)
	}
	if !verified {
		return ErrSecurityCheckRequired
	}
	return nil
}

// securityCheckEnabled answers within the caller's transaction so a setting
// flipped mid-request cannot be read twice with different answers.
func securityCheckEnabled(ctx context.Context, tx pgx.Tx) (bool, error) {
	settings, err := getSecurityCheckSettings(ctx, tx, true)
	if err != nil {
		return false, err
	}
	return settings.Enabled, nil
}

// securityRelevantChange reports whether an edit changes what a reviewer was
// shown. Everything an owner can type is relevant: a reviewer who approved one
// service URL did not approve another.
func securityRelevantChange(before model.App, input model.AppInput) bool {
	return before.Name != input.Name || before.Slug != input.Slug ||
		before.Summary != input.Summary || before.Description != input.Description ||
